fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many elements to consider
    let limit = n as usize;
    let considered = if participations.len() < limit {
        participations.len()
    } else {
        limit
    };

    // Count eligible participants
    let eligible_count = participations
        .iter()
        .take(considered)
        .filter(|&&sessions| 5 - sessions >= k)
        .count();

    // Maximum number of disjoint teams (integer division by 3)
    (eligible_count / 3) as u8
}